  return api.put(`/venuesdev/${venue.id}/services/booking/${params.id}/replace/court`, omit(params, ['id']))
}

export const getAllBookingReactive = (dates: string[]) => {
  const venue = useVenueStore().venue
  if (dates.length <= 14) {
    return db.collection('venues')
      .doc(venue.id)
      .collection('services')
      .doc('booking')
      .collection('scheduling')
      .where('status', 'in', ['BOOKED', 'PENDING'])
      .where('date', 'in', dates)
  } else {
    return db.collection('venues')
      .doc(venue.id)
      .collection('services')
      .doc('booking')
      .collection('scheduling')
      .where('status', 'in', ['BOOKED'])
      .where('date', 'in', dates)
  }
}

